import java.util.List;
import java.util.regex.Pattern;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;

if (prefix == null || prefix.isBlank() || prefix.length() > 50) {
    throw new IllegalArgumentException("Invalid title prefix");
}
Pattern pattern = Pattern.compile("^" + Pattern.quote(prefix));
Query query = new Query(Criteria.where("title").regex(pattern));
query.limit(20);
List<JournalEntry> entries = mongoTemplate.find(query, JournalEntry.class);

import java.util.List;
import org.springframework.data.mongodb.core.query.Criteria;
import org.springframework.data.mongodb.core.query.Query;

Query query = new Query(Criteria.where("sentimentAnalysis").is(true));
query.addCriteria(Criteria.where("email").exists(true).ne(null));
query.limit(100);
List<User> users = mongoTemplate.find(query, User.class);
